const rnd = Math.random().toString(16).slice(2) + Math.random().toString(16).slice(2);
const correlation_id = '14a-' + Date.now().toString(16) + '-' + rnd.slice(0,12);
const d = new Date();
const dateStr = d.toISOString().slice(0,10);
return [{ json: { correlation_id, dateStr, startedAt: d.toISOString() } }];

const init = $('Init Run').first().json;
const r = $json || {};
// New kill-switch contract: { mode, advisory_on, autonomous_on, enabled }.
// Safe fallback to legacy 'enabled' until the backend deploys the new fields.
const hasAdvisory = (r.advisory_on !== undefined && r.advisory_on !== null);
const hasAutonomous = (r.autonomous_on !== undefined && r.autonomous_on !== null);
// advisory_on (mode>=1) falls back to legacy enabled: proceed unless explicitly disabled.
const advisory_on = hasAdvisory ? (r.advisory_on === true) : (r.enabled !== false);
// autonomous_on (mode>=2) FAILS CLOSED when absent: mutations only run when backend explicitly says mode>=2.
const autonomous_on = hasAutonomous ? (r.autonomous_on === true) : false;
return [{ json: {
  correlation_id: init.correlation_id,
  dateStr: init.dateStr,
  startedAt: init.startedAt,
  mode: (r.mode !== undefined ? r.mode : null),
  advisory_on,
  autonomous_on,
  killSwitchEnabled: (r.enabled !== undefined ? r.enabled : null),
  killSwitchRaw: (r.raw !== undefined ? r.raw : null),
  proceed: advisory_on
} }];

const c = $('Capture Ranking').first().json;
const regime = c.regime || {};
const leak = c.leak || {};
const decay = c.decay || {};
const ranking = c.ranking || {};
const leaks = Array.isArray(leak.leaks) ? leak.leaks : [];
const leakHigh = leaks.filter(l => l && l.severity === 'high').length;
const leakWarn = leaks.filter(l => l && l.severity === 'warning').length;
const reportInput = {
  date: c.dateStr, correlation_id: c.correlation_id,
  regime: { detected: (regime.regime || regime.regime_label || regime.classification || null), raw: regime },
  leak_detection: { run_id: (leak.run_id || null), strategies_scanned: (leak.strategies_scanned || 0), total_leaks: leaks.length, high: leakHigh, warning: leakWarn, leaks: leaks.slice(0,15) },
  edge_decay: decay, composite_ranking: ranking
};
const fb = [];
fb.push('3AM Nightly Intelligence Report - ' + c.dateStr);
fb.push('Regime: ' + (reportInput.regime.detected || 'n/a'));
fb.push('Leaks: ' + leaks.length + ' total (' + leakHigh + ' high, ' + leakWarn + ' warning) across ' + (leak.strategies_scanned||0) + ' strategies');
fb.push('Composite ranking: ' + JSON.stringify((ranking.data?.counts ?? ranking.counts ?? ranking.verdicts ?? ranking)).slice(0,300));
fb.push('Correlation: ' + c.correlation_id);
const fallbackText = fb.join('\n');
const systemPrompt = 'You are an institutional trading-desk risk analyst writing a concise nightly brief for a solo futures operator. Summarize ONLY the JSON provided. Do NOT invent data, numbers, strategy names, or recommendations not present in the input. If a section is empty or errored, state that plainly. Output tight markdown, max ~250 words, titled "3AM Nightly Intelligence Report". Cover market regime, leak-detection findings (highlight any high severity), edge-decay alerts, and composite health ranking.';
const userPrompt = 'Synthesize tonight\'s nightly intelligence from this JSON. Do not add anything not present in the data:\n' + JSON.stringify(reportInput);
return [{ json: { correlation_id: c.correlation_id, dateStr: c.dateStr, reportInput, fallbackText, systemPrompt, userPrompt } }];

const asm = $('Assemble Report').first().json;
const gpt = $json || {};
let report = '';
try { report = (gpt.choices && gpt.choices[0] && gpt.choices[0].message && gpt.choices[0].message.content) ? gpt.choices[0].message.content : ''; } catch(e){ report = ''; }
const usedFallback = !report;
if (usedFallback) report = asm.fallbackText;
return [{ json: { correlation_id: asm.correlation_id, dateStr: asm.dateStr, title: '3AM Nightly Intelligence Report - ' + asm.dateStr, message: String(report).slice(0,1800), severity: 'info', usedFallback } }];

const ctx = $('Capture Ranking').first().json;
const data = $json;
const list = Array.isArray(data) ? data : ((data && (data.data || data.backtests)) || []);
return list.filter(b => b && b.id).slice(0,10).map(b => ({ json: { strategy_id: (b.strategyId || b.strategy_id || null), backtest_id: b.id, correlation_id: ctx.correlation_id, dateStr: ctx.dateStr } }));

const all = $input.all();
const ctx = $('Capture Ranking').first().json;
return [{ json: { source: '14a_organ_drive', correlation_id: ctx.correlation_id, date: ctx.dateStr, organs_driven: all.length, note: 'Drove critique + critic-optimizer over ' + all.length + ' recent backtests' } }];

